import { getParticipants } from '../../query/participants/getParticipants.mjs';
import { getParticipantId } from '../../functions/global/extractors.mjs';
import { definedAttributes } from '../../tools/definedAttributes.mjs';
import { findParticipant } from '../../acquire/findParticipant.mjs';
import { addParticipants } from './addParticipants.mjs';
import { UUID } from '../../tools/UUID.mjs';
import { participantRoles } from '../../constants/participantRoles.mjs';
import { INDIVIDUAL, PAIR } from '../../constants/participantConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';
import { MISSING_TOURNAMENT_RECORD, INVALID_VALUES, INVALID_PARTICIPANT_ROLE } from '../../constants/errorConditionConstants.mjs';
import { COMPETITOR } from '../../constants/participantRoleValues.mjs';

function addPersons({ participantRole = COMPETITOR, tournamentRecord, persons }) {
    if (!tournamentRecord)
        return { error: MISSING_TOURNAMENT_RECORD };
    if (!Array.isArray(persons))
        return { error: INVALID_VALUES };
    if (!Object.keys(participantRoles).includes(participantRole))
        return { error: INVALID_PARTICIPANT_ROLE };
    const existingPersonIds = new Set((tournamentRecord.participants ?? []).map(({ person }) => person?.personId).filter(Boolean));
    const newPersonIds = [];
    const personsToAdd = persons
        .filter((person) => person &&
        (!person.personId || !existingPersonIds.has(person.personId)))
        .map((person) => {
        person.personId ??= UUID();
        newPersonIds.push(person.personId);
        return person;
    });
    const excludeAttributes = (element, attributes) => {
        return Object.assign({}, ...Object.keys(element)
            .filter((key) => !attributes.includes(key))
            .map((key) => ({ [key]: element[key] })));
    };
    const individualParticipants = personsToAdd.map((person) => definedAttributes({
        extensions: person.participantExtensions,
        timeItems: person.participantTimeItems,
        participantType: INDIVIDUAL,
        participantRole,
        person: excludeAttributes(person, ['participantExtensions', 'participantTimeItems', 'pairedPersons']),
    }));
    let addedPairParticipantsCount = 0;
    let addedIndividualParticipantsCount;
    let result = addParticipants({
        participants: individualParticipants,
        tournamentRecord,
    });
    if (result.error)
        return result;
    addedIndividualParticipantsCount = result.addedCount || 0;
    const pairParticipants = [];
    const tournamentParticipants = getParticipants({
        participantFilters: { participantTypes: [INDIVIDUAL] },
        tournamentRecord,
    })?.participants ?? [];
    if (participantRole === COMPETITOR) {
        persons
            .filter(({ pairedPersons }) => pairedPersons)
            .forEach(({ personId, pairedPersons }) => {
            Array.isArray(pairedPersons) &&
                pairedPersons.forEach((pairing) => {
                    const individualParticipants = [personId, pairing.personId]
                        .map((id) => findParticipant({ tournamentParticipants, personId: id }))
                        .filter(Boolean);
                    if (individualParticipants.length === 2) {
                        const individualParticipantIds = individualParticipants.map(getParticipantId);
                        pairParticipants.push(definedAttributes({
                            extensions: pairing.participantExtensions,
                            timeItems: pairing.timeItems,
                            participantRole: COMPETITOR,
                            individualParticipantIds,
                            participantType: PAIR,
                        }));
                    }
                });
        });
    }
    if (pairParticipants.length) {
        result = addParticipants({
            participants: pairParticipants,
            tournamentRecord,
        });
        if (result.error)
            return result;
        addedPairParticipantsCount = result.addedCount || 0;
    }
    const addedCount = addedIndividualParticipantsCount + addedPairParticipantsCount;
    return { ...SUCCESS, addedCount, newPersonIds };
}

export { addPersons };
