import { modifyEventEntriesNotice } from '../notifications/entriesNotifications.mjs';
import { getPairedParticipant } from '../../query/participant/getPairedParticipant.mjs';
import { addParticipants } from '../participants/addParticipants.mjs';
import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { intersection } from '../../tools/arrays.mjs';
import { INVALID_PARTICIPANT_IDS } from '../../constants/errorConditionConstants.mjs';
import { TOURNAMENT_RECORD, EVENT } from '../../constants/attributeConstants.mjs';
import { INDIVIDUAL, PAIR } from '../../constants/participantConstants.mjs';
import { MAIN } from '../../constants/drawDefinitionConstants.mjs';
import { COMPETITOR } from '../../constants/participantRoleValues.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';
import { DIRECT_ACCEPTANCE, UNGROUPED } from '../../constants/entryStatusValues.mjs';

function modifyEventEntries({ entryStatus = DIRECT_ACCEPTANCE, unpairedParticipantIds = [], participantIdPairs = [], entryStage = MAIN, tournamentRecord, event, }) {
    const paramsCheck = requireParams({ tournamentRecord, event }, [TOURNAMENT_RECORD, EVENT]);
    if (paramsCheck.error)
        return paramsCheck;
    const tournamentParticipants = tournamentRecord.participants ?? [];
    const individualParticipantIds = tournamentParticipants
        .filter((participant) => participant.participantType === INDIVIDUAL)
        .map((participant) => participant.participantId);
    const incomingIndividualParticipantIds = unpairedParticipantIds.concat(...participantIdPairs).flat(Infinity);
    const invalidParticipantIds = incomingIndividualParticipantIds.filter((participantId) => !individualParticipantIds.includes(participantId));
    if (invalidParticipantIds.length)
        return { error: INVALID_PARTICIPANT_IDS, invalidParticipantIds };
    const invalidParticipantIdPairs = participantIdPairs.filter((pair) => pair.length !== 2);
    if (invalidParticipantIdPairs.length)
        return { error: INVALID_PARTICIPANT_IDS, invalidParticipantIdPairs };
    const existingParticipantIdPairs = tournamentParticipants
        .filter((participant) => participant.participantType === PAIR)
        .map((participant) => participant.individualParticipantIds);
    const newParticipantIdPairs = participantIdPairs.filter((incoming) => !existingParticipantIdPairs.find((existing) => intersection(existing, incoming).length === 2));
    const newParticipants = newParticipantIdPairs.map((individualParticipantIds) => ({
        participantType: PAIR,
        participantRole: COMPETITOR,
        individualParticipantIds,
    }));
    const result = addParticipants({
        participants: newParticipants,
        tournamentRecord,
    });
    if (result.error)
        return result;
    const pairParticipantEntries = participantIdPairs
        .map((participantIds) => {
        const { participant } = getPairedParticipant({
            tournamentRecord,
            participantIds,
        });
        return participant;
    })
        .map((participantId) => ({
        participantId,
        entryStatus,
        entryStage,
    }));
    const unpairedParticipantEntries = unpairedParticipantIds.map((participantId) => ({
        entryStatus: UNGROUPED,
        participantId,
        entryStage,
    }));
    event.entries = (event.entries ?? []).filter((entry) => entry.entryStage === entryStage);
    event.entries = event.entries.concat(...pairParticipantEntries, ...unpairedParticipantEntries);
    modifyEventEntriesNotice({ event, tournamentId: tournamentRecord?.tournamentId });
    return { ...SUCCESS };
}

export { modifyEventEntries };
