import { ARRAY, TOURNAMENT_RECORDS, OF_TYPE, SCHEDULE_DATES, VALIDATE } from '../../../constants/attributeConstants.mjs';
import { DO_NOT_SCHEDULE } from '../../../constants/requestConstants.mjs';
